<?php declare(strict_types=1);require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/database.php';require_once __DIR__.'/includes/auth.php';$db=db();$e=fn($v)=>htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['payment_id'])){$p=$db->prepare('SELECT * FROM invoice_payments WHERE id=?');$p->execute([(int)$_POST['payment_id']]);$pay=$p->fetch();if($pay){$i=$db->prepare('SELECT id,total FROM invoices WHERE id=?');$i->execute([(int)$pay['invoice_id']]);$inv=$i->fetch();if($inv){$amount=(float)$pay['amount'];$expected=(float)$inv['total'];$diff=round($amount-$expected,2);$status=abs($diff)<0.01?'matched':($diff>0?'overpaid':'underpaid');$q=$db->prepare('INSERT INTO payment_reconciliations(payment_id,invoice_id,expected_amount,actual_amount,difference,status,reconciled_at) VALUES(?,?,?,?,?,?,NOW()) ON DUPLICATE KEY UPDATE expected_amount=VALUES(expected_amount),actual_amount=VALUES(actual_amount),difference=VALUES(difference),status=VALUES(status),reconciled_at=NOW()');$q->execute([$pay['id'],$inv['id'],$expected,$amount,$diff,$status]);}}}$rows=$db->query('SELECT p.id,p.invoice_id,p.amount,p.method,p.reference,p.paid_at,i.invoice_number,i.total,COALESCE(r.status,"unreconciled") reconciliation_status FROM invoice_payments p JOIN invoices i ON i.id=p.invoice_id LEFT JOIN payment_reconciliations r ON r.payment_id=p.id ORDER BY p.paid_at DESC,p.id DESC')->fetchAll();?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Payment Reconciliation</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-4"><h1 class="h3">Payment Reconciliation</h1><div class="card"><div class="card-body"><table class="table align-middle"><thead><tr><th>Invoice</th><th>Payment</th><th>Expected</th><th>Difference</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rows as $r):$diff=(float)$r['amount']-(float)$r['total'];?><tr><td><?=$e($r['invoice_number'])?></td><td><?=$e($r['amount'])?></td><td><?=$e($r['total'])?></td><td><?=number_format($diff,2)?></td><td><?=$e($r['reconciliation_status'])?></td><td><?php if($r['reconciliation_status']==='unreconciled'):?><form method="post"><input type="hidden" name="payment_id" value="<?=$r['id']?>"><button class="btn btn-sm btn-dark">Reconcile</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div></main></body></html>